 "content": "def transform(grid):
    """Replicate the lone non-marker panel motif across panels, row-colored by the first column."""
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    sep_rows = [r for r, row in enumerate(g) if row and all(v == row[0] and row[0] != 0 for v in row)]
    sep_cols = [c for c in range(w) if g[0][c] != 0 and all(g[r][c] == g[0][c] for r in range(h))]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    panels = [[(row_bounds[i] + 1, row_bounds[i + 1], col_bounds[j] + 1, col_bounds[j + 1])
               for j in range(len(col_bounds) - 1)] for i in range(len(row_bounds) - 1)]

    # The motif is the sole occupied panel outside the first column.
    candidates = []
    for i, panel_row in enumerate(panels):
        for j, (r0, r1, c0, c1) in enumerate(panel_row):
            if j == 0:
                continue
            cells = [(r - r0, c - c0) for r in range(r0, r1) for c in range(c0, c1) if g[r][c] != 0]
            if cells:
                candidates.append((r0, r1, c0, c1, cells))
    if len(candidates) != 1:
        raise ValueError(f"expected one motif panel, found {len(candidates)}")
    _, _, _, _, motif = candidates[0]

    # The marker color for each panel row is read from its first panel.
    row_colors = []
    for panel_row in panels:
        r0, r1, c0, c1 = panel_row[0]
        colors = [g[r][c] for r in range(r0, r1) for c in range(c0, c1) if g[r][c] != 0]
        if not colors:
            raise ValueError("missing row marker")
        row_colors.append(max(set(colors), key=colors.count))

    out = [row[:] for row in g]
    for i, panel_row in enumerate(panels):
        for r0, r1, c0, c1 in panel_row:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in motif:
                out[r0 + dr][c0 + dc] = row_colors[i]
    return out
